-- Добавляем workout_logs для каждой из 25 тренировок, которые мы создали
-- Это логирование завершенной тренировки со всем её историей

-- Сначала очищаем старые workout_logs для этого пользователя
DELETE FROM exercise_sets WHERE exercise_log_id IN (
  SELECT el.id FROM exercise_logs el
  INNER JOIN workout_logs wl ON el.workout_log_id = wl.id
  WHERE wl.user_id = '22222222-2222-2222-2222-222222222222'
);
DELETE FROM exercise_logs WHERE workout_log_id IN (
  SELECT id FROM workout_logs WHERE user_id = '22222222-2222-2222-2222-222222222222'
);
DELETE FROM workout_logs WHERE user_id = '22222222-2222-2222-2222-222222222222';

-- Добавляем workout_logs для каждой workout

-- Добавляем exercise_logs (для каждого упражнения в workout с сложностью)

SELECT COUNT(*) as total_logs FROM exercise_logs;
SELECT COUNT(*) as total_workout_logs FROM workout_logs WHERE user_id = '22222222-2222-2222-2222-222222222222';
